#!/bin/sh
# static 内部链接：两个模块的同名私有函数互不冲突
# 期望输出见 expected_output（本机 MinGW 工具链真实执行捕获）

cat > a.c << 'EOF'
static int secret(void)
{
    return 1;
}

int api_a(void)
{
    return secret();
}
EOF

cat > b.c << 'EOF'
static int secret(void)
{
    return 2;
}

int api_b(void)
{
    return secret();
}
EOF

cat > main.c << 'EOF'
#include <stdio.h>

int api_a(void);
int api_b(void);

int main(void)
{
    printf("api_a() = %d, api_b() = %d\n", api_a(), api_b());
    return 0;
}
EOF

gcc -c a.c -o a.o
gcc -c b.c -o b.o
nm a.o     # secret 是小写 t：内部链接，不进全局符号表
nm b.o     # 同名 secret 仍是小写 t，两者不会冲突
gcc main.o 2>/dev/null || gcc -c main.c -o main.o
gcc main.o a.o b.o -o app && ./app
./app
